import { useEffect, useId, useRef } from 'react'
import type { WaveRenderer } from './waveRenderer'

export default function Ribbon() {
  const id = useId().replace(/:/g, '')
  const ref = useRef<HTMLDivElement>(null)
  const canvasRef = useRef<HTMLCanvasElement>(null)
  useEffect(() => {
    const root = ref.current
    const canvas = canvasRef.current
    if (!root || !canvas) return
    root.dataset.state = 'pending'
    root.dataset.running = 'false'
    let renderer: WaveRenderer | null = null
    let disposed = false
    let loading = false
    let visible = false
    let frame = 0
    let time = 0
    let previous = 0
    let lastDraw = 0
    const media = window.matchMedia('(prefers-reduced-motion: reduce)')
    const coarsePointer = window.matchMedia('(pointer: coarse)')
    const header = root.closest('.mf-site')?.querySelector('.mf-site-header')
    const home = root.closest('.mf-home')
    const canRun = () =>
      visible &&
      !document.hidden &&
      !media.matches &&
      home?.getAttribute('data-motion-running') !== 'false' &&
      header?.getAttribute('data-open') !== 'true'
    const draw = (now: number) => {
      if (disposed || !renderer || !canRun()) {
        frame = 0
        return
      }
      if (previous) time += Math.min(now - previous, 64)
      previous = now
      // Follow the display on desktop. Keep the remainder on touch devices so
      // throttling cannot accumulate a long frame every few draws.
      const interval = 1000 / 30
      const elapsed = now - lastDraw
      if (!coarsePointer.matches || elapsed >= interval) {
        renderer.draw(time)
        lastDraw = coarsePointer.matches ? now - (elapsed % interval) : now
      }
      frame = requestAnimationFrame(draw)
    }
    const update = () => {
      const running = canRun() && !!renderer
      root.dataset.running = String(running)
      if (running && !frame) {
        previous = 0
        frame = requestAnimationFrame(draw)
      } else if (!running && frame) {
        cancelAnimationFrame(frame)
        frame = 0
        previous = 0
      }
    }
    const load = async () => {
      if (renderer || loading || disposed || media.matches) return
      loading = true
      try {
        const { createWaveRenderer } = await import('./waveRenderer')
        if (disposed || media.matches) return
        renderer = createWaveRenderer(canvas)
        if (renderer) {
          renderer.draw(time)
          root.dataset.state = 'ready'
          update()
        } else {
          root.dataset.state = 'fallback'
        }
      } catch {
        if (!disposed) {
          renderer?.dispose()
          renderer = null
          root.dataset.state = 'fallback'
          update()
        }
      } finally {
        loading = false
      }
    }
    const onMotionChange = () => {
      if (visible) void load()
      update()
    }
    const observer = new IntersectionObserver(([entry]) => {
      visible = entry.isIntersecting
      if (visible) void load()
      update()
    })
    const resize = new ResizeObserver(() => {
      renderer?.resize()
      renderer?.draw(time)
    })
    const navigation = new MutationObserver(update)
    const theme = new MutationObserver(() => {
      renderer?.updateColors()
      // Redraw even when reduced motion or a hidden tab has paused the loop.
      renderer?.draw(time)
    })
    observer.observe(root)
    resize.observe(canvas)
    theme.observe(document.documentElement, {
      attributes: true,
      attributeFilter: ['data-mf-theme'],
    })
    if (header) navigation.observe(header, { attributes: true, attributeFilter: ['data-open'] })
    if (home)
      navigation.observe(home, { attributes: true, attributeFilter: ['data-motion-running'] })
    media.addEventListener('change', onMotionChange)
    document.addEventListener('visibilitychange', update)
    const onContextLost = (event: Event) => {
      event.preventDefault()
      if (frame) cancelAnimationFrame(frame)
      frame = 0
      renderer?.dispose()
      renderer = null
      root.dataset.state = 'fallback'
      root.dataset.running = 'false'
    }
    const onContextRestored = () => {
      if (visible) void load()
    }
    canvas.addEventListener('webglcontextlost', onContextLost)
    canvas.addEventListener('webglcontextrestored', onContextRestored)
    return () => {
      disposed = true
      cancelAnimationFrame(frame)
      observer.disconnect()
      resize.disconnect()
      navigation.disconnect()
      theme.disconnect()
      media.removeEventListener('change', onMotionChange)
      document.removeEventListener('visibilitychange', update)
      canvas.removeEventListener('webglcontextlost', onContextLost)
      canvas.removeEventListener('webglcontextrestored', onContextRestored)
      renderer?.dispose()
    }
  }, [])
  return (
    <div ref={ref} className='mf-hero-ribbon' data-state='pending' aria-hidden='true'>
      <svg viewBox='0 0 1400 800' preserveAspectRatio='xMidYMid slice' focusable='false'>
        <defs>
          <linearGradient id={`${id}-silk`} x1='0' y1='0' x2='1' y2='.8'>
            <stop stopColor='var(--mf-wave-light)' />
            <stop offset='.3' stopColor='var(--mf-wave-primary)' />
            <stop offset='.7' stopColor='var(--mf-wave-accent)' />
            <stop offset='1' stopColor='var(--mf-wave-light)' />
          </linearGradient>
          <linearGradient id={`${id}-mist`} x1='1' y1='0' x2='0' y2='1'>
            <stop stopColor='var(--mf-wave-accent)' />
            <stop offset='.5' stopColor='var(--mf-wave-light)' />
            <stop offset='1' stopColor='var(--mf-wave-depth)' />
          </linearGradient>
        </defs>
        <path
          d='M-160 90 C220 430 530 -120 930 30 S1290 360 1560 130 L1540 310 C1230 550 940 120 710 200 S230 550 -160 270 Z'
          fill={`url(#${id}-mist)`}
        />
        <path
          d='M-160 510 C240 270 480 790 860 580 S1250 290 1560 560 L1540 770 C1180 460 1030 860 680 810 S160 500 -160 760 Z'
          fill={`url(#${id}-silk)`}
        />
      </svg>
      <canvas ref={canvasRef} />
    </div>
  )
}
